  File.WriteAllText(capture,"ORANGE_WORKSHOP_1\n"+nonce+"\nexample.test:16261\n2\n123\n456\nEND\n");Check(ServerWorkshopCatalog.Capture(Path.Combine(root,"data"),"example.test:16261",nonce,capture),"complete bound capture accepted");
  var prepType=typeof(ServerWorkshopTests).Assembly.GetType("PZ3D.ServerWorkshopPreparation");Check(prepType!=null,"background coordinator available");
  using(var entered=new ManualResetEventSlim(false))using(var release=new ManualResetEventSlim(false)){int calls=0;using(var c=new ModernController(Path.Combine(root,"steamapps","common","game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true,null,(e,a,p,progress,token,batch)=>{Interlocked.Increment(ref calls);Check(a=="download"&&(bool)p["confirmed"],"existing download boundary");entered.Set();release.Wait(token);progress(37,"37 / 100 bytes");if((string)p["id"]=="456")throw new IOException("fixture item failed");return new{id=p["id"],message="verified"};})){
   var m=Manifest(c);var p=new Dictionary<string,object>{{"id",m["id"]},{"stamp",m["stamp"]},{"confirmed",true}};var watch=System.Diagnostics.Stopwatch.StartNew();var start=D(c.Execute("serverWorkshopPrepare",p));Check(watch.ElapsedMilliseconds<1000,"prepare immediately returns");Check(entered.Wait(2000),"owned worker entered");var duplicate=D(c.Execute("serverWorkshopPrepare",p));Check((string)duplicate["jobId"]==(string)start["jobId"]&&calls==1,"duplicate does not subscribe twice");c.Execute("serverList",null);c.Execute("serverWorkshopImport",new Dictionary<string,object>{{"id",m["id"]},{"stamp",m["stamp"]},{"text","999"},{"confirmed",true}});var ordinary=new LauncherJournal(Path.Combine(root,"data"));string ordinaryId=ordinary.Begin("settingsSave","Fixture settings edit");ordinary.Update(25,"Settings remain usable");var listing=D(c.Execute("serverList",null));c.Execute("serverUpsert",new Dictionary<string,object>{{"stamp",listing["stamp"]},{"id",m["id"]},{"name","Edited during preparation"},{"host","new-job.test"},{"port",16261},{"queryPort",0},{"username",""},{"useSteamRelay",false}});release.Set();var done=Wait(c);ordinary.Finish("completed","Fixture saved");var history=(System.Collections.IList)D(ordinary.Snapshot())["history"];Check(history.Cast<Dictionary<string,object>>().Any(x=>(string)x["id"]==ordinaryId&&(string)x["status"]=="completed"),"preparation does not overwrite simultaneous normal journal");Check((string)done["endpoint"]=="job.test:16261","endpoint edits do not retarget owned worker");Check((string)done["state"]=="partial"&&Convert.ToInt32(done["completedItems"])==2,"one failed item yields partial verified successes");Check((string)done["manifestStamp"]==(string)m["stamp"]&&Convert.ToInt32(done["totalItems"])==3,"import cannot relabel running job");Check(calls==3,"processes original batch only");
  }}
  using(var entered=new ManualResetEventSlim(false)){int calls=0;using(var c=new ModernController(Path.Combine(root,"steamapps","common","game"),Path.Combine(root,"user"),Path.Combine(root,"cancel-data"),true,null,(e,a,p,progress,token,batch)=>{Interlocked.Increment(ref calls);entered.Set();token.WaitHandle.WaitOne();token.ThrowIfCancellationRequested();return null;})){var m=Manifest(c);var start=D(c.Execute("serverWorkshopPrepare",new Dictionary<string,object>{{"id",m["id"]},{"stamp",m["stamp"]},{"confirmed",true}}));Check(entered.Wait(2000),"cancel worker entered");Reject(()=>c.AssertCanRestart(),"active preparation blocks launcher restart");c.Execute("serverWorkshopCancel",new Dictionary<string,object>{{"jobId",start["jobId"]}});Check((string)Wait(c)["state"]=="cancelled"&&calls==1,"cancel prevents later items and drains worker");}}
  using(var c=new ModernController(Path.Combine(root,"steamapps","common","game"),Path.Combine(root,"user"),Path.Combine(root,"complete-data"),true,null,(e,a,p,progress,token,batch)=>new{id=p["id"],message="verified"})){var m=Manifest(c);c.Execute("serverWorkshopPrepare",new Dictionary<string,object>{{"id",m["id"]},{"stamp",m["stamp"]},{"confirmed",true}});Check((string)Wait(c)["state"]=="completed","all verified successes complete");}
  var session=new Engine(Path.Combine(root,"session-game"),Path.Combine(root,"session-user"),Path.Combine(root,"session-data"),true);Directory.CreateDirectory(session.Game);File.WriteAllText(session.Config,"{\"vmArgs\":[]}");LaunchProfiles.Stage(session,new ProfileLaunchRequest{Kind="server",Host="example.test",Port=16261,Username="fixture"});var sessionRecord=json.Deserialize<ProfileSessionRecord>(File.ReadAllText(LaunchProfiles.Journal(session)));string requestNonce=File.ReadAllLines(Path.Combine(session.User,"Lua","OrangeLauncherSession.request.txt"))[1];Check(requestNonce==sessionRecord.Nonce,"capture binds existing request and journal nonce");File.WriteAllText(Path.Combine(session.User,"Lua","OrangeLauncherWorkshop.txt"),"ORANGE_WORKSHOP_1\n"+requestNonce+"\nexample.test:16261\n1\n123\nEND\n");LaunchProfiles.Recover(session,true);Check(Directory.GetFiles(Path.Combine(session.Data,"server-workshop")).Length==1&&!LaunchProfiles.Pending(session),"capture imported before association recovery");
  string jobFolder=Path.Combine(root,"complete-data","server-workshop-jobs");Check(Directory.Exists(jobFolder),"job snapshots survive launcher restart");string jobFile=Directory.GetFiles(jobFolder).Single();var envelope=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(jobFile));envelope["ownerPid"]=-1;((Dictionary<string,object>)envelope["snapshot"])["state"]="running";File.WriteAllText(jobFile,json.Serialize(envelope));using(var recovered=new ServerWorkshopPreparation(Path.Combine(root,"complete-data"),null)){Check((string)D(recovered.Status())["state"]=="interrupted","abandoned owned job explicitly interrupted");}
  using(var entered=new ManualResetEventSlim(false)){int calls=0;using(var c=new ModernController(Path.Combine(root,"steamapps","common","game"),Path.Combine(root,"user"),Path.Combine(root,"launch-data"),true,null,(e,a,p,progress,token,batch)=>{Interlocked.Increment(ref calls);entered.Set();token.WaitHandle.WaitOne();token.ThrowIfCancellationRequested();return null;})){var m=Manifest(c);c.Execute("serverWorkshopPrepare",new Dictionary<string,object>{{"id",m["id"]},{"stamp",m["stamp"]},{"confirmed",true}});Check(entered.Wait(2000),"launch drain worker entered");Reject(()=>c.Execute("launch",new Dictionary<string,object>()),"fixture prohibits real launch");Check((string)Wait(c)["state"]=="cancelled"&&calls==1,"explicit launch drains only owned preparation before dispatch");}}
  string badData=Path.Combine(root,"bad-data");Directory.CreateDirectory(badData);File.WriteAllText(Path.Combine(badData,"server-workshop"),"occupied");Reject(()=>ServerWorkshopCatalog.Capture(badData,"example.test:16261",nonce,capture),"actual capture write errors remain visible to diagnostic caller");
  Console.WriteLine("PASS ServerWorkshopTests "+checks+" checks");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
